		return flt(row.rate, precision("rate", row)) === derived;
	}

	async function on_rate(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		// only a positive rate can be a base (a discount on an empty row can drive it negative)
		if (flt(row.rate) <= 0 || rate_comes_from_discount(row) || !(await follows_rate(frm, row))) return;

		// a rate the user typed is the new base, without any earlier discount
		use_rate_as_base(row);
		row.discount_percentage = 0;
		row.discount_amount = 0;
	}

	// a row saved before this app may have a Rate but no Price List Rate yet
	async function on_discount(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (flt(row.price_list_rate) || flt(row.rate) <= 0 || !(await follows_rate(frm, row))) return;
		use_rate_as_base(row);
	}

	ITEM_DOCTYPES.forEach((doctype) => {
		frappe.ui.form.on(doctype, {
			rate: on_rate,
			discount_percentage: on_discount,
			discount_amount: on_discount,
		});
	});
})();

// Keep Additional Discount off item rows flagged "No Discount Applicable".
//
// Client-side mirror of erpnext_no_discount/overrides/taxes_and_totals.py.
// Without this the form would show a different discount than the server saves.
(function () {
	if (!window.erpnext || !erpnext.taxes_and_totals) return;

	const proto = erpnext.taxes_and_totals.prototype;
	if (proto.__no_discount_patched) return;
	proto.__no_discount_patched = true;

	const FLAG = "custom_no_discount_applicable";

	function flagged_rows(frm) {
		return (frm.doc.items || []).filter((r) => r[FLAG] && !r.is_alternative);
	}

	const _set_discount_amount = proto.set_discount_amount;
	proto.set_discount_amount = function () {
		const rows = flagged_rows(this.frm);
		const pct = this.frm.doc.additional_discount_percentage;
		if (!rows.length || !pct || !this.frm.doc.apply_discount_on) {
			return _set_discount_amount.apply(this, arguments);
		}
		let base = flt(this.frm.doc[frappe.scrub(this.frm.doc.apply_discount_on)]);
		rows.forEach((r) => { base -= flt(r.net_amount); });
		this.frm.doc.discount_amount = flt((base * pct) / 100, precision("discount_amount"));
	};

	const _get_total = proto.get_total_for_discount_amount;
	proto.get_total_for_discount_amount = function () {
		let total = _get_total.apply(this, arguments);
		flagged_rows(this.frm).forEach((r) => { total -= flt(r.net_amount); });
		return flt(total);
	};

	const _apply_discount_amount = proto.apply_discount_amount;
	proto.apply_discount_amount = function () {
		const rows = flagged_rows(this.frm);
		if (!rows.length || !this.frm.doc.discount_amount) {
			return _apply_discount_amount.apply(this, arguments);
		}
		const original_items = this.frm._items || [];
		this.frm._items = original_items.filter((r) => !r[FLAG]);
		try {
			_apply_discount_amount.apply(this, arguments);
		} finally {
			this.frm._items = original_items;
		}
		this._calculate_taxes_and_totals();
	};
})();

// Row discounts on items that have no Item Price.
//
// ERPNext takes a row's discount from its Price List Rate, and wipes the discount (sales)
// or zeroes the rate (purchase) when there is none. On rows without an Item Price:
//   - a Rate the user types becomes the Price List Rate (discount reset),
//   - every discount is taken from that Price List Rate and stays on the row,
//   - a Rate ERPNext works out from the discount leaves both alone.
//   Rate 100             -> Price List Rate 100, Rate 100
//   Discount 10%         -> Price List Rate 100, Rate 90,  Discount 10%
//   Discount 5%          -> Price List Rate 100, Rate 95,  Discount 5%
//   Rate 120             -> Price List Rate 120, Rate 120, Discount 0
// Form handlers run before the ERPNext controller's own ones, so the row is set up before
// ERPNext applies the discount or reacts to the new rate.
// Rows with an Item Price, a pricing rule or a blanket order rate keep standard behaviour.
(function () {
	if (window.__no_discount_base_rate_bound) return;
	window.__no_discount_base_rate_bound = true;

	const ITEM_DOCTYPES = [
		"Quotation Item",
		"Sales Order Item",
		"Delivery Note Item",
		"Sales Invoice Item",
		"POS Invoice Item",
		"Supplier Quotation Item",
		"Purchase Order Item",
		"Purchase Receipt Item",
		"Purchase Invoice Item",
	];

	// item_code + price list -> whether an Item Price exists
	const item_price_cache = new Map();

	async function has_item_price(frm, row) {
		const price_list = frm.doc.selling_price_list || frm.doc.buying_price_list;
		if (!price_list || !row.item_code) return false;

		const key = `${row.item_code}::${price_list}`;
		if (!item_price_cache.has(key)) {
			try {
				const r = await frappe.db.get_value("Item Price", { item_code: row.item_code, price_list }, "name");
				item_price_cache.set(key, !!r?.message?.name);
			} catch (e) {
				// cannot tell: leave the row to standard ERPNext behaviour
				item_price_cache.set(key, true);
			}
		}
		return item_price_cache.get(key);
	}

	async function follows_rate(frm, row) {
		if (row.pricing_rules || row.blanket_order_rate) return false;
		return !(await has_item_price(frm, row));
	}

	function use_rate_as_base(row) {
		row.price_list_rate = row.rate;
		row.margin_type = "";
		row.margin_rate_or_amount = 0;
	}

	// true when the rate is exactly what ERPNext derives from the row's discount
	function rate_comes_from_discount(row) {
		if (!flt(row.discount_amount) || !flt(row.price_list_rate)) return false;
		const derived = flt(flt(row.price_list_rate) - flt(row.discount_amount), precision("rate", row));
		return flt(row.rate, precision("rate", row)) === derived;
	}

	async function on_rate(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		// only a positive rate can be a base (a discount on an empty row can drive it negative)
		if (flt(row.rate) <= 0 || rate_comes_from_discount(row) || !(await follows_rate(frm, row))) return;

		// a rate the user typed is the new base, without any earlier discount
		use_rate_as_base(row);
		row.discount_percentage = 0;
		row.discount_amount = 0;
	}

	// a row saved before this app may have a Rate but no Price List Rate yet
	async function on_discount(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (flt(row.price_list_rate) || flt(row.rate) <= 0 || !(await follows_rate(frm, row))) return;
		use_rate_as_base(row);
	}

	ITEM_DOCTYPES.forEach((doctype) => {
		frappe.ui.form.on(doctype, {
			rate: on_rate,
			discount_percentage: on_discount,
			discount_amount: on_discount,
		});
	});
})();
